window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-1843a67c3929e77c"]={"versions": [{"id": "FIG-1843a67c3929e77c", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> UML-Klassendiagramm (Ausschnitt des M2-Metamodells der AUTOSAR Classic Platform, <em>Software Component Template</em>).\n</li><li><strong>Technischer Zweck:</strong> Definition des Typ- und Aggregationsmusters für <code>ValueSpecification</code>. Es stellt das zentrale Konzept zur formalen, plattform- und sprachunabhängigen Modellierung von statischen Datenwerten, Initialisierungswerten (<code>initValue</code>), Kalibrierwerten (Calibration Parameters) und Konstanten (<code>ConstantSpecification</code>) im ARXML dar.\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Zentrale Abstraktion</h5>\n<ul class=\"fig-list\"><li><strong><code>ValueSpecification</code> (abstrakt):</strong> Basisklasse aller Werteausprägungen im AUTOSAR-Metamodell.\n<ul class=\"fig-list\"><li>Attribut: <code>shortLabel: Identifier [0..1]</code> – Optionaler Bezeichner, primär genutzt zur Zuordnung von Werten zu Feldern in zusammengesetzten Typen (z. B. Strukturfeldern).\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">Container / Wurzel-Element</h5>\n<ul class=\"fig-list\"><li><strong><code>ConstantSpecification</code>:</strong> Spezialisierung von <code>ARElement</code> (autonom paketierbares Modell-Element).\n<ul class=\"fig-list\"><li>Komposition: Hält über die Rolle <code>+valueSpec</code> exakt eine Instanz (<code>1</code>) von <code>ValueSpecification</code>.\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">Spezialisierungen von <code>ValueSpecification</code> (Subklassen)</h5>\n<ul class=\"fig-list\"><li><strong><code>NumericalValueSpecification</code>:</strong> Repräsentiert skalare numerische Konstanten (Ganzzahl, Gleitkomma).\n<ul class=\"fig-list\"><li>Attribut: <code>value: Numerical</code> (Stereotyp <code>«atpVariation»</code>).\n</li></ul>\n</li><li><strong><code>TextValueSpecification</code>:</strong> Repräsentiert Zeichenkettenliterale.\n<ul class=\"fig-list\"><li>Attribut: <code>value: VerbatimString</code>.\n</li></ul>\n</li><li><strong><code>ArrayValueSpecification</code>:</strong> Repräsentiert zusammengesetzte Vektoren/Listen.\n<ul class=\"fig-list\"><li>Komposition: Aggregiert geordnete Kind-Elemente über <code>+element: ValueSpecification [1..*] {ordered}</code>. Rekursive Verschachtelung beliebiger <code>ValueSpecification</code>-Subklassen möglich.\n</li><li>Stereotyp: <code>«atpVariation»</code> mit Tag <code>Vh.latestBindingTime = PreCompileTime</code>.\n</li></ul>\n</li><li><strong><code>RecordValueSpecification</code>:</strong> Repräsentiert C-Strukturen (<code>struct</code>) bzw. heterogene Verbundtypen.\n<ul class=\"fig-list\"><li>Komposition: Aggregiert geordnete Strukturfelder über <code>+field: ValueSpecification [1..*] {ordered}</code>. Rekursive Verschachtelung möglich.\n</li><li>Stereotyp: <code>«atpVariation»</code> mit Tag <code>Vh.latestBindingTime = PreCompileTime</code>.\n</li></ul>\n</li><li><strong><code>ConstantReference</code>:</strong> Indirektion zur Wiederverwendung bereits definierter Konstanten (DRY-Prinzip).\n<ul class=\"fig-list\"><li>Assoziation: Referenziert über <code>+constant [1]</code> zielgerichtet eine existierende <code>ConstantSpecification</code>.\n</li></ul>\n</li><li><strong><code>ReferenceValueSpecification</code>:</strong> Modelliert Pointer- bzw. Adress-Initialisierungen.\n<ul class=\"fig-list\"><li>Assoziation: Referenziert über <code>+referenceValue [1]</code> ein Ziel vom Typ <code>DataPrototype</code> (welches das Metamodell-Stereotyp/Interface <code>AtpPrototype</code> implementiert).\n</li></ul>\n</li><li><strong><code>ApplicationValueSpecification</code>:</strong> Abstrakte Wertdefinition auf Ebene der Applikationstypen vor der Transformation in Implementierungs-Datentypen (<code>ImplementationDataType</code>).\n<ul class=\"fig-list\"><li>Attribut: <code>category: Identifier</code> (bestimmt die Semantik des Werts).\n</li></ul>\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf (Generierungszeit)</h4>\n<p class=\"fig-p\">Da es sich um ein statisches Metamodell handelt, existiert kein Laufzeit-Zustandswechsel. Der Verarbeitungsablauf erfolgt tooling- und generierungszeitlich:</p>\n<ol class=\"fig-list\"><li><strong>ARXML-Authoring &amp; Aggregation:</strong> SWC-Entwickler oder Kalibriertools definieren Initialwerte für <code>VariableDataPrototype</code> oder <code>ParameterDataPrototype</code> via geschachtelter <code>ValueSpecification</code>-Bäume.\n</li><li><strong>Pre-Compile Variant Handling:</strong> Bindung der mit <code>«atpVariation»</code> annotierten Pfade (<code>value</code>, <code>element</code>, <code>field</code>) auf Basis der System-Constant-Werte. Auflösung struktureller und numerischer Varianzen bis spätestens zur Vorkompilierphase.\n</li><li><strong>RTE-/BSW-Codegenerierung:</strong>\n<ul class=\"fig-list\"><li>Rekursive Traversierung der <code>ArrayValueSpecification</code>- und <code>RecordValueSpecification</code>-Hierarchien unter Berücksichtigung des <code>{ordered}</code>-Constraints.\n</li><li>Generierung von C99-Initialisierungslisten (<code>{ .field = val, ... }</code> bzw. <code>{ val1, val2 }</code>), <code>const</code>-Strukturen für ROM/Flash oder NvM-Default-RAM-Blöcken.\n</li><li>Auflösung von <code>ReferenceValueSpecification</code> in C-Symboladressen (<code>&amp;variable</code>).\n</li></ul>\n</li></ol>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Reihenfolgentreue (<code>{ordered}</code>):</strong> Sowohl bei <code>ArrayValueSpecification</code> (<code>+element</code>) als auch bei <code>RecordValueSpecification</code> (<code>+field</code>) ist die XML-Elementreihenfolge strikt normativ. Die RTE mappt die Werte elementweise auf die Reihenfolge der Struktur- bzw. Array-Member im korrespondierenden <code>ImplementationDataType</code>. Ein Fehlmapping im ARXML führt direkt zu Fehlinizialisierungen im C-Code.\n</li><li><strong>Variabilitätsgrenze (Binding Time):</strong> Das Tag <code>Vh.latestBindingTime = PreCompileTime</code> schließt eine Post-Build-Variabilität (z. B. via <code>PostBuildSelectable</code> oder <code>PostBuildLoadable</code>) für die innere Struktur von Arrays und Records an dieser Stelle aus. Strukturdimensionen und Feldvorhandensein müssen vor dem C-Compiler-Lauf feststehen.\n</li><li><strong>Typkonsistenz beim RTE-Build:</strong> Der RTE-Generator validiert <code>ValueSpecification</code> gegen den assoziierten <code>AutosarDataType</code>. Typ-Inkompatibilitäten (z. B. <code>TextValueSpecification</code> für einen Integer-Typ oder Kardinalitätsverletzung zwischen Array-Länge und deklarierter <code>element</code>-Anzahl) führen zum Abbruch der Codegenerierung.\n</li><li><strong>Speicherlayout-Zuordnung:</strong> Werte aus <code>ConstantSpecification</code> werden durch nachgelagerte Memory-Mapping-Mechanismen (<code>SwAddrMethod</code>, <code>MemMap.h</code>) typischerweise in schreibgeschützten Bereichen (<code>CONST</code>, Flash) abgelegt, während <code>ValueSpecification</code>-Bäume an <code>VariableDataPrototype</code> als Initialisierungsvektoren im Startup-Code (<code>.data</code>-Init) oder NvM-Redundanzblöcken landen.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-28dd2a178e37715c", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> UML-Klassendiagramm (Ausschnitt des M2-Metamodells der AUTOSAR Classic Platform, <em>Software Component Template</em>).\n</li><li><strong>Technischer Zweck:</strong> Definition des Typ- und Aggregationsmusters für <code>ValueSpecification</code>. Es stellt das zentrale Konzept zur formalen, plattform- und sprachunabhängigen Modellierung von statischen Datenwerten, Initialisierungswerten (<code>initValue</code>), Kalibrierwerten (Calibration Parameters) und Konstanten (<code>ConstantSpecification</code>) im ARXML dar.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Zentrale Abstraktion</h5>\n<ul class=\"fig-list\"><li><strong><code>ValueSpecification</code> (abstrakt):</strong> Basisklasse aller Werteausprägungen im AUTOSAR-Metamodell.\n<ul class=\"fig-list\"><li>Attribut: <code>shortLabel :Identifier [0..1]</code> – Optionaler Bezeichner, primär genutzt zur Zuordnung von Werten zu Feldern in zusammengesetzten Typen.\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">Container / Wurzel-Element</h5>\n<ul class=\"fig-list\"><li><strong><code>ConstantSpecification</code>:</strong> Spezialisierung von <code>ARElement</code> (autonom paketierbares Modell-Element).\n<ul class=\"fig-list\"><li>Komposition: Hält über die Rolle <code>+valueSpec</code> exakt eine Instanz (<code>1</code>) von <code>ValueSpecification</code>.\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">Spezialisierungen von <code>ValueSpecification</code> (Subklassen)</h5>\n<ul class=\"fig-list\"><li><strong><code>NumericalValueSpecification</code>:</strong> Repräsentiert skalare numerische Konstanten.\n<ul class=\"fig-list\"><li>Attribut: <code>value :Numerical</code> (Stereotyp <code>«atpVariation»</code>).\n</li></ul>\n</li><li><strong><code>TextValueSpecification</code>:</strong> Repräsentiert Zeichenkettenliterale.\n<ul class=\"fig-list\"><li>Attribut: <code>value :VerbatimString</code>.\n</li></ul>\n</li><li><strong><code>ArrayValueSpecification</code>:</strong> Repräsentiert zusammengesetzte Vektoren/Listen.\n<ul class=\"fig-list\"><li>Komposition: Aggregiert geordnete Kind-Elemente über <code>+element 1..* {ordered}</code> vom Typ <code>ValueSpecification</code>.\n</li><li>Stereotyp: <code>«atpVariation»</code> mit Tag <code>vh.latestBindingTime = preCompileTime</code>.\n</li></ul>\n</li><li><strong><code>RecordValueSpecification</code>:</strong> Repräsentiert heterogene Verbundtypen (C-Strukturen).\n<ul class=\"fig-list\"><li>Komposition: Aggregiert geordnete Strukturfelder über <code>+field 1..* {ordered}</code> vom Typ <code>ValueSpecification</code>.\n</li><li>Stereotyp: <code>«atpVariation»</code> mit Tag <code>vh.latestBindingTime = preCompileTime</code>.\n</li></ul>\n</li><li><strong><code>ConstantReference</code>:</strong> Indirektion zur Wiederverwendung bereits definierter Konstanten.\n<ul class=\"fig-list\"><li>Assoziation: Referenziert über <code>+constant 1</code> eine <code>ConstantSpecification</code>.\n</li></ul>\n</li><li><strong><code>ReferenceValueSpecification</code>:</strong> Modelliert Pointer- bzw. Adress-Initialisierungen.\n<ul class=\"fig-list\"><li>Assoziation: Referenziert über <code>+referenceValue 1</code> ein Ziel vom Typ <code>DataPrototype</code> (Stereotyp <code>AtpPrototype</code>).\n</li></ul>\n</li><li><strong><code>ApplicationValueSpecification</code>:</strong> Abstrakte Wertdefinition auf Ebene der Applikationstypen.\n<ul class=\"fig-list\"><li>Attribut: <code>category :Identifier</code>.\n</li></ul>\n</li><li><strong><code>AbstractRuleBasedValueSpecification</code> (abstrakt):</strong> Basisklasse für regelbasierte Wertdefinitionen.\n<ul class=\"fig-list\"><li>Subklassen:\n<ul class=\"fig-list\"><li><strong><code>NumericalRuleBasedValueSpecification</code>:</strong> Regelbasierte Erzeugung numerischer Wertefolgen.\n</li><li><strong><code>ApplicationRuleBasedValueSpecification</code>:</strong> Regelbasierte Erzeugung auf Applikationsebene; besitzt das Attribut <code>category :Identifier</code>.\n</li></ul>\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Da es sich um ein statisches Metamodell handelt, existiert kein Laufzeit-Zustandswechsel. Der Verarbeitungsablauf erfolgt tooling- und generierungszeitlich:</p>\n<ol class=\"fig-list\"><li><strong>ARXML-Authoring &amp; Aggregation:</strong> SWC-Entwickler oder Kalibriertools definieren Initialwerte für <code>VariableDataPrototype</code> oder <code>ParameterDataPrototype</code> via geschachtelter <code>ValueSpecification</code>-Bäume.\n</li><li><strong>Pre-Compile Variant Handling:</strong> Bindung der mit <code>«atpVariation»</code> annotierten Pfade (<code>value</code>, <code>element</code>, <code>field</code>) auf Basis der System-Constant-Werte. Auflösung struktureller und numerischer Varianzen bis spätestens zur Vorkompilierphase.\n</li><li><strong>RTE-/BSW-Codegenerierung:</strong>\n<ul class=\"fig-list\"><li>Rekursive Traversierung der <code>ArrayValueSpecification</code>- und <code>RecordValueSpecification</code>-Hierarchien unter Berücksichtigung des <code>{ordered}</code>-Constraints.\n</li><li>Generierung von C99-Initialisierungslisten (<code>{ .field = val, ... }</code> bzw. <code>{ val1, val2 }</code>), <code>const</code>-Strukturen für ROM/Flash oder NvM-Default-RAM-Blöcken.\n</li><li>Auflösung von <code>ReferenceValueSpecification</code> in C-Symboladressen (<code>&amp;variable</code>).\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Modellierungsregeln:</strong> Jede <code>ConstantSpecification</code> erfordert zwingend eine <code>ValueSpecification</code> (<code>+valueSpec 1</code>).\n</li><li><strong>Regelbasierte Initialisierung:</strong> Ergänzend zu expliziten Elementlisten stehen regelbasierte Ausprägungen (<code>AbstractRuleBasedValueSpecification</code>) für numerische und applikative Werte zur Verfügung.\n</li><li><strong>Kardinalitäten:</strong> Zusammengesetzte Werte (<code>ArrayValueSpecification</code>, <code>RecordValueSpecification</code>) erfordern mindestens ein Element bzw. Feld (<code>1..* {ordered}</code>).\n</li><li><strong>Variantenbindung:</strong> Die Bindungszeit für <code>«atpVariation»</code> an Feldern und Elementen ist formell als <code>vh.latestBindingTime = preCompileTime</code> spezifiziert.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-2377b1f4d59eca7b", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> UML-Klassendiagramm (Ausschnitt des M2-Metamodells der AUTOSAR Classic Platform, <em>Software Component Template</em>).\n</li><li><strong>Technischer Zweck:</strong> Definition des Typ- und Aggregationsmusters für <code>ValueSpecification</code>. Es stellt das zentrale Konzept zur formalen, plattform- und sprachunabhängigen Modellierung von statischen Datenwerten, Initialisierungswerten (<code>initValue</code>), Kalibrierwerten (Calibration Parameters) und Konstanten (<code>ConstantSpecification</code>) im ARXML dar.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Zentrale Abstraktion</h5>\n<ul class=\"fig-list\"><li><strong><code>ValueSpecification</code> (abstrakt):</strong> Basisklasse aller Werteausprägungen im AUTOSAR-Metamodell.\n<ul class=\"fig-list\"><li>Attribut: <code>shortLabel :Identifier [0..1]</code> – Optionaler Bezeichner, primär genutzt zur Zuordnung von Werten zu Feldern in zusammengesetzten Typen.\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">Container / Wurzel-Element</h5>\n<ul class=\"fig-list\"><li><strong><code>ConstantSpecification</code>:</strong> Spezialisierung von <code>ARElement</code> (autonom paketierbares Modell-Element).\n<ul class=\"fig-list\"><li>Komposition: Hält über die Rolle <code>+valueSpec</code> exakt eine Instanz (<code>1</code>) von <code>ValueSpecification</code>.\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">Spezialisierungen von <code>ValueSpecification</code> (Subklassen)</h5>\n<ul class=\"fig-list\"><li><strong><code>NumericalValueSpecification</code>:</strong> Repräsentiert skalare numerische Konstanten.\n<ul class=\"fig-list\"><li>Attribut: <code>value :Numerical</code> (Stereotyp <code>«atpVariation»</code>).\n</li></ul>\n</li><li><strong><code>TextValueSpecification</code>:</strong> Repräsentiert Zeichenkettenliterale.\n<ul class=\"fig-list\"><li>Attribut: <code>value :VerbatimString</code>.\n</li></ul>\n</li><li><strong><code>ArrayValueSpecification</code>:</strong> Repräsentiert zusammengesetzte Vektoren/Listen.\n<ul class=\"fig-list\"><li>Komposition: Aggregiert geordnete Kind-Elemente über <code>+element 1..* {ordered}</code> vom Typ <code>ValueSpecification</code>.\n</li><li>Stereotyp: <code>«atpVariation»</code> mit Tag <code>vh.latestBindingTime = preCompileTime</code>.\n</li></ul>\n</li><li><strong><code>RecordValueSpecification</code>:</strong> Repräsentiert heterogene Verbundtypen (C-Strukturen).\n<ul class=\"fig-list\"><li>Komposition: Aggregiert geordnete Strukturfelder über <code>+field 1..* {ordered}</code> vom Typ <code>ValueSpecification</code>.\n</li><li>Stereotyp: <code>«atpVariation»</code> mit Tag <code>vh.latestBindingTime = preCompileTime</code>.\n</li></ul>\n</li><li><strong><code>ConstantReference</code>:</strong> Indirektion zur Wiederverwendung bereits definierter Konstanten.\n<ul class=\"fig-list\"><li>Assoziation: Referenziert über <code>+constant 1</code> eine <code>ConstantSpecification</code>.\n</li></ul>\n</li><li><strong><code>ReferenceValueSpecification</code>:</strong> Modelliert Pointer- bzw. Adress-Initialisierungen.\n<ul class=\"fig-list\"><li>Assoziation: Referenziert über <code>+referenceValue 1</code> ein Ziel vom Typ <code>DataPrototype</code> (Stereotyp <code>AtpPrototype</code>).\n</li></ul>\n</li><li><strong><code>ApplicationValueSpecification</code>:</strong> Abstrakte Wertdefinition auf Ebene der Applikationstypen.\n<ul class=\"fig-list\"><li>Attribut: <code>category :Identifier</code>.\n</li></ul>\n</li><li><strong><code>AbstractRuleBasedValueSpecification</code> (abstrakt):</strong> Basisklasse für regelbasierte Wertdefinitionen.\n<ul class=\"fig-list\"><li>Subklassen:\n<ul class=\"fig-list\"><li><strong><code>NumericalRuleBasedValueSpecification</code>:</strong> Regelbasierte Erzeugung numerischer Wertefolgen.\n</li><li><strong><code>ApplicationRuleBasedValueSpecification</code>:</strong> Regelbasierte Erzeugung auf Applikationsebene; besitzt das Attribut <code>category :Identifier</code>.\n</li></ul>\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Da es sich um ein statisches Metamodell handelt, existiert kein Laufzeit-Zustandswechsel. Der Verarbeitungsablauf erfolgt tooling- und generierungszeitlich:</p>\n<ol class=\"fig-list\"><li><strong>ARXML-Authoring &amp; Aggregation:</strong> SWC-Entwickler oder Kalibriertools definieren Initialwerte für <code>VariableDataPrototype</code> oder <code>ParameterDataPrototype</code> via geschachtelter <code>ValueSpecification</code>-Bäume.\n</li><li><strong>Pre-Compile Variant Handling:</strong> Bindung der mit <code>«atpVariation»</code> annotierten Pfade (<code>value</code>, <code>element</code>, <code>field</code>) auf Basis der System-Constant-Werte. Auflösung struktureller und numerischer Varianzen bis spätestens zur Vorkompilierphase.\n</li><li><strong>RTE-/BSW-Codegenerierung:</strong>\n<ul class=\"fig-list\"><li>Rekursive Traversierung der <code>ArrayValueSpecification</code>- und <code>RecordValueSpecification</code>-Hierarchien unter Berücksichtigung des <code>{ordered}</code>-Constraints.\n</li><li>Generierung von C99-Initialisierungslisten (<code>{ .field = val, ... }</code> bzw. <code>{ val1, val2 }</code>), <code>const</code>-Strukturen für ROM/Flash oder NvM-Default-RAM-Blöcken.\n</li><li>Auflösung von <code>ReferenceValueSpecification</code> in C-Symboladressen (<code>&amp;variable</code>).\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Modellierungsregeln:</strong> Jede <code>ConstantSpecification</code> erfordert zwingend eine <code>ValueSpecification</code> (<code>+valueSpec 1</code>).\n</li><li><strong>Regelbasierte Initialisierung:</strong> Ergänzend zu expliziten Elementlisten stehen regelbasierte Ausprägungen (<code>AbstractRuleBasedValueSpecification</code>) für numerische und applikative Werte zur Verfügung.\n</li><li><strong>Kardinalitäten:</strong> Zusammengesetzte Werte (<code>ArrayValueSpecification</code>, <code>RecordValueSpecification</code>) erfordern mindestens ein Element bzw. Feld (<code>1..* {ordered}</code>).\n</li><li><strong>Variantenbindung:</strong> Die Bindungszeit für <code>«atpVariation»</code> an Feldern und Elementen ist formell als <code>vh.latestBindingTime = preCompileTime</code> spezifiziert.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-f20434401f077538", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> UML-Klassendiagramm (Ausschnitt des M2-Metamodells der AUTOSAR Classic Platform, <em>Software Component Template</em>).\n</li><li><strong>Technischer Zweck:</strong> Definition des Typ- und Aggregationsmusters für <code>ValueSpecification</code>. Es stellt das zentrale Konzept zur formalen, plattform- und sprachunabhängigen Modellierung von statischen Datenwerten, Initialisierungswerten (<code>initValue</code>), Kalibrierwerten (Calibration Parameters) und Konstanten (<code>ConstantSpecification</code>) im ARXML dar.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Zentrale Abstraktion</h5>\n<ul class=\"fig-list\"><li><strong><code>ValueSpecification</code> (abstrakt):</strong> Basisklasse aller Werteausprägungen im AUTOSAR-Metamodell.\n<ul class=\"fig-list\"><li>Attribut: <code>shortLabel :Identifier [0..1]</code>.\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">Container / Wurzel-Element</h5>\n<ul class=\"fig-list\"><li><strong><code>ConstantSpecification</code>:</strong> Spezialisierung von <code>ARElement</code>.\n<ul class=\"fig-list\"><li>Komposition: Hält über die Rolle <code>+valueSpec</code> exakt eine Instanz (<code>1</code>) von <code>ValueSpecification</code>.\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">Spezialisierungen von <code>ValueSpecification</code></h5>\n<ul class=\"fig-list\"><li><strong><code>ConstantReference</code>:</strong> Indirektion zu einer <code>ConstantSpecification</code> über <code>+constant 1</code>.\n</li><li><strong><code>NumericalValueSpecification</code>:</strong> Numerischer Skalarwert; Attribut <code>value :Numerical</code> mit <code>«atpVariation»</code>.\n</li><li><strong><code>ReferenceValueSpecification</code>:</strong> Adress-/Pointer-Referenzierung auf <code>DataPrototype</code> (<code>AtpPrototype</code>) über <code>+referenceValue 1</code>.\n</li><li><strong><code>TextValueSpecification</code>:</strong> Zeichenkettenliteral mit Attribut <code>value :VerbatimString</code>.\n</li><li><strong><code>ApplicationValueSpecification</code>:</strong> Spezifikation auf Applikationsebene; Attribut <code>category :Identifier</code>.\n</li><li><strong><code>CompositeValueSpecification</code> (abstrakt):</strong> Gemeinsame Basisklasse für zusammengesetzte Werte; erbt von <code>ValueSpecification</code>.\n<ul class=\"fig-list\"><li><strong><code>ArrayValueSpecification</code>:</strong> Aggregiert über <code>+element 1..* {ordered}</code> Kind-<code>ValueSpecification</code> (Stereotyp <code>«atpVariation»</code>, Tag <code>vh.latestBindingTime = preCompileTime</code>).\n</li><li><strong><code>RecordValueSpecification</code>:</strong> Aggregiert über <code>+field 1..* {ordered}</code> Strukturfeld-<code>ValueSpecification</code> (Stereotyp <code>«atpVariation»</code>, Tag <code>vh.latestBindingTime = preCompileTime</code>).\n</li></ul>\n</li><li><strong><code>AbstractRuleBasedValueSpecification</code> (abstrakt):</strong> Basisklasse für regelbasierte Wertdefinitionen.\n<ul class=\"fig-list\"><li><strong><code>NumericalRuleBasedValueSpecification</code>:</strong> Numerische regelbasierte Ausprägung.\n</li><li><strong><code>ApplicationRuleBasedValueSpecification</code>:</strong> Applikative regelbasierte Ausprägung; Attribut <code>category :Identifier</code>.\n</li><li><strong><code>CompositeRuleBasedValueSpecification</code>:</strong> Regelbasierte Definition zusammengesetzter Strukturen.\n<ul class=\"fig-list\"><li>Attribute: <code>maxSizeToFill :PositiveInteger [0..1]</code>, <code>rule :Identifier</code>.\n</li><li>Komposition: Aggregiert über <code>+argument 1..* {ordered}</code> Instanzen von <code>CompositeValueSpecification</code>.\n</li></ul>\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Da es sich um ein statisches Metamodell handelt, existiert kein Laufzeit-Zustandswechsel. Der Verarbeitungsablauf erfolgt tooling- und generierungszeitlich:</p>\n<ol class=\"fig-list\"><li><strong>ARXML-Authoring &amp; Aggregation:</strong> SWC-Entwickler oder Kalibriertools definieren Initialwerte für <code>VariableDataPrototype</code> oder <code>ParameterDataPrototype</code> via geschachtelter <code>ValueSpecification</code>-Bäume.\n</li><li><strong>Pre-Compile Variant Handling:</strong> Bindung der mit <code>«atpVariation»</code> annotierten Pfade (<code>value</code>, <code>element</code>, <code>field</code>) auf Basis der System-Constant-Werte. Auflösung struktureller und numerischer Varianzen bis spätestens zur Vorkompilierphase.\n</li><li><strong>RTE-/BSW-Codegenerierung:</strong>\n<ul class=\"fig-list\"><li>Rekursive Traversierung der <code>ArrayValueSpecification</code>- und <code>RecordValueSpecification</code>-Hierarchien unter Berücksichtigung des <code>{ordered}</code>-Constraints.\n</li><li>Generierung von C99-Initialisierungslisten (<code>{ .field = val, ... }</code> bzw. <code>{ val1, val2 }</code>), <code>const</code>-Strukturen für ROM/Flash oder NvM-Default-RAM-Blöcken.\n</li><li>Auflösung von <code>ReferenceValueSpecification</code> in C-Symboladressen (<code>&amp;variable</code>).\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Zusammengesetzte Typen:</strong> Die gemeinsame Vererbungshierarchie bündelt Vektoren (<code>ArrayValueSpecification</code>) und Strukturen (<code>RecordValueSpecification</code>) unter der abstrakten <code>CompositeValueSpecification</code>.\n</li><li><strong>Regelbasierte Zusammensetzung:</strong> <code>CompositeRuleBasedValueSpecification</code> ermöglicht die algorithmische Erzeugung komplexer Wertekonfigurationen basierend auf übergebenen Argumenten (<code>+argument 1..* {ordered}</code>) und einer Spezifikationsregel (<code>rule</code>), optional begrenzt durch <code>maxSizeToFill</code>.\n</li><li><strong>Vollständigkeit:</strong> Arrays, Records und Composite-Regelargumente bedingen mindestens eine Kind-Spezifikation (<code>1..*</code>).\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-02f6b563e67886c9", "releases": ["R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> UML-Klassendiagramm (Ausschnitt des M2-Metamodells der AUTOSAR Classic Platform, <em>Software Component Template</em>).\n</li><li><strong>Technischer Zweck:</strong> Definition des Typ- und Aggregationsmusters für <code>ValueSpecification</code>. Es stellt das zentrale Konzept zur formalen, plattform- und sprachunabhängigen Modellierung von statischen Datenwerten, Initialisierungswerten (<code>initValue</code>), Kalibrierwerten (Calibration Parameters) und Konstanten (<code>ConstantSpecification</code>) im ARXML dar.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Zentrale Abstraktion</h5>\n<ul class=\"fig-list\"><li><strong><code>ValueSpecification</code> (abstrakt):</strong> Basisklasse aller Werteausprägungen im Metamodell.\n<ul class=\"fig-list\"><li>Attribut: <code>shortLabel: Identifier [0..1]</code>.\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">Container / Wurzel-Element</h5>\n<ul class=\"fig-list\"><li><strong><code>ConstantSpecification</code>:</strong> Spezialisierung von <code>ARElement</code>.\n<ul class=\"fig-list\"><li>Komposition: Hält über die Rolle <code>+valueSpec</code> exakt eine Instanz (<code>1</code>) von <code>ValueSpecification</code>.\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">Spezialisierungen von <code>ValueSpecification</code></h5>\n<ul class=\"fig-list\"><li><strong><code>ConstantReference</code>:</strong> Indirektion zu einer <code>ConstantSpecification</code> über <code>+constant 1</code>.\n</li><li><strong><code>NumericalValueSpecification</code>:</strong> Numerischer Skalarwert; Attribut <code>value: Numerical</code> mit <code>«atpVariation»</code>.\n</li><li><strong><code>ReferenceValueSpecification</code>:</strong> Referenzierung auf <code>DataPrototype</code> (<code>AtpPrototype</code>) über <code>+referenceValue 1</code>.\n</li><li><strong><code>TextValueSpecification</code>:</strong> Zeichenkettenliteral mit Attribut <code>value: VerbatimString</code>.\n</li><li><strong><code>ApplicationValueSpecification</code>:</strong> Spezifikation auf Applikationsebene; Attribut <code>category: Identifier</code>.\n</li><li><strong><code>CompositeValueSpecification</code> (abstrakt):</strong> Basisklasse für zusammengesetzte Werte; erbt von <code>ValueSpecification</code>.\n<ul class=\"fig-list\"><li><strong><code>ArrayValueSpecification</code>:</strong> Aggregiert über <code>+element 0..* {ordered}</code> Kind-<code>ValueSpecification</code> (Stereotyp <code>«atpVariation»</code>, Tag <code>vh.latestBindingTime = preCompileTime</code>).\n</li><li><strong><code>RecordValueSpecification</code>:</strong> Aggregiert über <code>+field 1..* {ordered}</code> Strukturfeld-<code>ValueSpecification</code> (Stereotyp <code>«atpVariation»</code>, Tag <code>vh.latestBindingTime = preCompileTime</code>).\n</li></ul>\n</li><li><strong><code>AbstractRuleBasedValueSpecification</code> (abstrakt):</strong> Basisklasse für regelbasierte Wertdefinitionen.\n<ul class=\"fig-list\"><li><strong><code>NumericalRuleBasedValueSpecification</code>:</strong> Numerische regelbasierte Ausprägung.\n</li><li><strong><code>ApplicationRuleBasedValueSpecification</code>:</strong> Applikative regelbasierte Ausprägung; Attribut <code>category: Identifier</code>.\n</li><li><strong><code>CompositeRuleBasedValueSpecification</code>:</strong> Regelbasierte Definition zusammengesetzter Strukturen.\n<ul class=\"fig-list\"><li>Attribute: <code>maxSizeToFill: PositiveInteger [0..1]</code>, <code>rule: Identifier</code>.\n</li><li>Komposition: Aggregiert über <code>+argument 1..* {ordered}</code> Instanzen von <code>CompositeValueSpecification</code>.\n</li></ul>\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Da es sich um ein statisches Metamodell handelt, existiert kein Laufzeit-Zustandswechsel. Der Verarbeitungsablauf erfolgt tooling- und generierungszeitlich:</p>\n<ol class=\"fig-list\"><li><strong>ARXML-Authoring &amp; Aggregation:</strong> SWC-Entwickler oder Kalibriertools definieren Initialwerte für <code>VariableDataPrototype</code> oder <code>ParameterDataPrototype</code> via geschachtelter <code>ValueSpecification</code>-Bäume.\n</li><li><strong>Pre-Compile Variant Handling:</strong> Bindung der mit <code>«atpVariation»</code> annotierten Pfade (<code>value</code>, <code>element</code>, <code>field</code>) auf Basis der System-Constant-Werte. Auflösung struktureller und numerischer Varianzen bis spätestens zur Vorkompilierphase.\n</li><li><strong>RTE-/BSW-Codegenerierung:</strong>\n<ul class=\"fig-list\"><li>Rekursive Traversierung der <code>ArrayValueSpecification</code>- und <code>RecordValueSpecification</code>-Hierarchien unter Berücksichtigung des <code>{ordered}</code>-Constraints.\n</li><li>Generierung von C99-Initialisierungslisten (<code>{ .field = val, ... }</code> bzw. <code>{ val1, val2 }</code>), <code>const</code>-Strukturen für ROM/Flash oder NvM-Default-RAM-Blöcken.\n</li><li>Auflösung von <code>ReferenceValueSpecification</code> in C-Symboladressen (<code>&amp;variable</code>).\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Leere Arrays:</strong> Durch die Kardinalität <code>+element 0..* {ordered}</code> an <code>ArrayValueSpecification</code> sind leere Arrays auf Modellebene zulässig.\n</li><li><strong>Strukturen:</strong> <code>RecordValueSpecification</code> verlangt weiterhin mindestens ein Feld (<code>1..* {ordered}</code>).\n</li><li><strong>Regelbasierte Zusammensetzung:</strong> <code>CompositeRuleBasedValueSpecification</code> verlangt mindestens ein Argument (<code>+argument 1..* {ordered}</code>) und referenziert eine Auswertungsregel <code>rule</code>.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-7944581b8e2dee93", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> UML-Klassendiagramm (Ausschnitt des M2-Metamodells der AUTOSAR Classic Platform, <em>Software Component Template</em>).\n</li><li><strong>Technischer Zweck:</strong> Definition des Typ- und Aggregationsmusters für <code>ValueSpecification</code>. Es stellt das zentrale Konzept zur formalen, plattform- und sprachunabhängigen Modellierung von statischen Datenwerten, Initialisierungswerten (<code>initValue</code>), Kalibrierwerten (Calibration Parameters) und Konstanten (<code>ConstantSpecification</code>) im ARXML dar.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Zentrale Abstraktion</h5>\n<ul class=\"fig-list\"><li><strong><code>ValueSpecification</code> (abstrakt):</strong> Basisklasse aller Werteausprägungen im Metamodell.\n<ul class=\"fig-list\"><li>Attribut: <code>shortLabel: Identifier [0..1]</code>.\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">Container / Wurzel-Element</h5>\n<ul class=\"fig-list\"><li><strong><code>ConstantSpecification</code>:</strong> Spezialisierung von <code>ARElement</code>.\n<ul class=\"fig-list\"><li>Komposition: Hält über die Rolle <code>+valueSpec</code> exakt eine Instanz (<code>1</code>) von <code>ValueSpecification</code>.\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">Spezialisierungen von <code>ValueSpecification</code></h5>\n<ul class=\"fig-list\"><li><strong><code>ConstantReference</code>:</strong> Indirektion zu einer <code>ConstantSpecification</code> über <code>+constant 1</code>.\n</li><li><strong><code>NumericalValueSpecification</code>:</strong> Numerischer Skalarwert; Attribut <code>value: Numerical</code> mit <code>«atpVariation»</code>.\n</li><li><strong><code>ReferenceValueSpecification</code>:</strong> Referenzierung auf <code>DataPrototype</code> (<code>AtpPrototype</code>) über <code>+referenceValue 1</code>.\n</li><li><strong><code>TextValueSpecification</code>:</strong> Zeichenkettenliteral mit Attribut <code>value: VerbatimString</code>.\n</li><li><strong><code>ApplicationValueSpecification</code>:</strong> Spezifikation auf Applikationsebene; Attribut <code>category: Identifier</code>.\n</li><li><strong><code>CompositeValueSpecification</code> (abstrakt):</strong> Basisklasse für zusammengesetzte Werte; erbt von <code>ValueSpecification</code>.\n<ul class=\"fig-list\"><li><strong><code>ArrayValueSpecification</code>:</strong> Repräsentiert zusammengesetzte Vektoren/Listen.\n<ul class=\"fig-list\"><li>Attribut: <code>intendedPartialInitializationCount: PositiveInteger [0..1]</code>.\n</li><li>Komposition: Aggregiert über <code>+element 0..* {ordered}</code> Kind-<code>ValueSpecification</code> (Stereotyp <code>«atpVariation»</code>, Tag <code>vh.latestBindingTime = preCompileTime</code>).\n</li></ul>\n</li><li><strong><code>RecordValueSpecification</code>:</strong> Aggregiert über <code>+field 1..* {ordered}</code> Strukturfeld-<code>ValueSpecification</code> (Stereotyp <code>«atpVariation»</code>, Tag <code>vh.latestBindingTime = preCompileTime</code>).\n</li></ul>\n</li><li><strong><code>AbstractRuleBasedValueSpecification</code> (abstrakt):</strong> Basisklasse für regelbasierte Wertdefinitionen.\n<ul class=\"fig-list\"><li><strong><code>NumericalRuleBasedValueSpecification</code>:</strong> Numerische regelbasierte Ausprägung.\n</li><li><strong><code>ApplicationRuleBasedValueSpecification</code>:</strong> Applikative regelbasierte Ausprägung; Attribut <code>category: Identifier</code>.\n</li><li><strong><code>CompositeRuleBasedValueSpecification</code>:</strong> Regelbasierte Definition zusammengesetzter Strukturen.\n<ul class=\"fig-list\"><li>Attribute: <code>maxSizeToFill: PositiveInteger [0..1]</code>, <code>rule: Identifier</code>.\n</li><li>Komposition: Aggregiert über <code>+argument 1..* {ordered}</code> Instanzen von <code>CompositeValueSpecification</code>.\n</li></ul>\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Da es sich um ein statisches Metamodell handelt, existiert kein Laufzeit-Zustandswechsel. Der Verarbeitungsablauf erfolgt tooling- und generierungszeitlich:</p>\n<ol class=\"fig-list\"><li><strong>ARXML-Authoring &amp; Aggregation:</strong> SWC-Entwickler oder Kalibriertools definieren Initialwerte für <code>VariableDataPrototype</code> oder <code>ParameterDataPrototype</code> via geschachtelter <code>ValueSpecification</code>-Bäume.\n</li><li><strong>Pre-Compile Variant Handling:</strong> Bindung der mit <code>«atpVariation»</code> annotierten Pfade (<code>value</code>, <code>element</code>, <code>field</code>) auf Basis der System-Constant-Werte. Auflösung struktureller und numerischer Varianzen bis spätestens zur Vorkompilierphase.\n</li><li><strong>RTE-/BSW-Codegenerierung:</strong>\n<ul class=\"fig-list\"><li>Rekursive Traversierung der <code>ArrayValueSpecification</code>- und <code>RecordValueSpecification</code>-Hierarchien unter Berücksichtigung des <code>{ordered}</code>-Constraints.\n</li><li>Generierung von C99-Initialisierungslisten (<code>{ .field = val, ... }</code> bzw. <code>{ val1, val2 }</code>), <code>const</code>-Strukturen für ROM/Flash oder NvM-Default-RAM-Blöcken.\n</li><li>Auflösung von <code>ReferenceValueSpecification</code> in C-Symboladressen (<code>&amp;variable</code>).\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Partielle Initialisierung:</strong> Über <code>intendedPartialInitializationCount: PositiveInteger [0..1]</code> kann an <code>ArrayValueSpecification</code> explizit modelliert werden, wie viele Elemente eines Arrays initialisiert werden sollen.\n</li><li><strong>Kardinalitäten:</strong> Arrays können mit 0 bis beliebig vielen Elementen instanziiert werden (<code>0..*</code>), während Records mindestens ein Feld (<code>1..*</code>) erfordern.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-5ec41143cb2dce14", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> UML-Klassendiagramm (Ausschnitt des M2-Metamodells der AUTOSAR Classic Platform, <em>Software Component Template</em>).\n</li><li><strong>Technischer Zweck:</strong> Definition des Typ- und Aggregationsmusters für <code>ValueSpecification</code>. Es stellt das zentrale Konzept zur formalen, plattform- und sprachunabhängigen Modellierung von statischen Datenwerten, Initialisierungswerten (<code>initValue</code>), Kalibrierwerten (Calibration Parameters) und Konstanten (<code>ConstantSpecification</code>) im ARXML dar.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Zentrale Abstraktion</h5>\n<ul class=\"fig-list\"><li><strong><code>ValueSpecification</code> (abstrakt):</strong> Basisklasse aller Werteausprägungen im Metamodell.\n<ul class=\"fig-list\"><li>Attribut: <code>shortLabel: Identifier [0..1]</code>.\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">Container / Wurzel-Element</h5>\n<ul class=\"fig-list\"><li><strong><code>ConstantSpecification</code>:</strong> Spezialisierung von <code>ARElement</code>.\n<ul class=\"fig-list\"><li>Komposition: Hält über die Rolle <code>+valueSpec</code> optional eine Instanz (<code>0..1</code>) von <code>ValueSpecification</code>.\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">Spezialisierungen von <code>ValueSpecification</code></h5>\n<ul class=\"fig-list\"><li><strong><code>ConstantReference</code>:</strong> Indirektion zu einer <code>ConstantSpecification</code> über <code>+constant 0..1</code>.\n</li><li><strong><code>NumericalValueSpecification</code>:</strong> Numerischer Skalarwert; Attribut <code>value: Numerical [0..1]</code> mit <code>«atpVariation»</code>.\n</li><li><strong><code>ReferenceValueSpecification</code>:</strong> Referenzierung auf <code>DataPrototype</code> (<code>AtpPrototype</code>) über <code>+referenceValue 0..1</code>.\n</li><li><strong><code>TextValueSpecification</code>:</strong> Zeichenkettenliteral mit optionalem Attribut <code>value: VerbatimString [0..1]</code>.\n</li><li><strong><code>ApplicationValueSpecification</code>:</strong> Spezifikation auf Applikationsebene; Attribut <code>category: Identifier [0..1]</code>.\n</li><li><strong><code>CompositeValueSpecification</code> (abstrakt):</strong> Basisklasse für zusammengesetzte Werte; erbt von <code>ValueSpecification</code>.\n<ul class=\"fig-list\"><li><strong><code>ArrayValueSpecification</code>:</strong> Repräsentiert Vektoren/Listen.\n<ul class=\"fig-list\"><li>Attribut: <code>intendedPartialInitializationCount: PositiveInteger [0..1]</code>.\n</li><li>Komposition: Aggregiert über <code>+element 0..* {ordered}</code> Kind-<code>ValueSpecification</code> (Stereotyp <code>«atpVariation»</code>, Tag <code>vh.latestBindingTime = preCompileTime</code>).\n</li></ul>\n</li><li><strong><code>RecordValueSpecification</code>:</strong> Aggregiert über <code>+field 0..* {ordered}</code> Strukturfeld-<code>ValueSpecification</code> (Stereotyp <code>«atpVariation»</code>, Tag <code>vh.latestBindingTime = preCompileTime</code>).\n</li></ul>\n</li><li><strong><code>AbstractRuleBasedValueSpecification</code> (abstrakt):</strong> Basisklasse für regelbasierte Wertdefinitionen.\n<ul class=\"fig-list\"><li><strong><code>NumericalRuleBasedValueSpecification</code>:</strong> Numerische regelbasierte Ausprägung.\n</li><li><strong><code>ApplicationRuleBasedValueSpecification</code>:</strong> Applikative regelbasierte Ausprägung; Attribut <code>category: Identifier [0..1]</code>.\n</li><li><strong><code>CompositeRuleBasedValueSpecification</code>:</strong> Regelbasierte Definition zusammengesetzter Strukturen.\n<ul class=\"fig-list\"><li>Attribute: <code>maxSizeToFill: PositiveInteger [0..1]</code>, <code>rule: Identifier [0..1]</code>.\n</li><li>Komposition: Aggregiert über <code>+argument 0..* {ordered}</code> Instanzen von <code>CompositeValueSpecification</code>.\n</li></ul>\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Da es sich um ein statisches Metamodell handelt, existiert kein Laufzeit-Zustandswechsel. Der Verarbeitungsablauf erfolgt tooling- und generierungszeitlich:</p>\n<ol class=\"fig-list\"><li><strong>ARXML-Authoring &amp; Aggregation:</strong> SWC-Entwickler oder Kalibriertools definieren Initialwerte für <code>VariableDataPrototype</code> oder <code>ParameterDataPrototype</code> via geschachtelter <code>ValueSpecification</code>-Bäume.\n</li><li><strong>Pre-Compile Variant Handling:</strong> Bindung der mit <code>«atpVariation»</code> annotierten Pfade (<code>value</code>, <code>element</code>, <code>field</code>) auf Basis der System-Constant-Werte. Auflösung struktureller und numerischer Varianzen bis spätestens zur Vorkompilierphase.\n</li><li><strong>RTE-/BSW-Codegenerierung:</strong>\n<ul class=\"fig-list\"><li>Rekursive Traversierung der <code>ArrayValueSpecification</code>- und <code>RecordValueSpecification</code>-Hierarchien unter Berücksichtigung des <code>{ordered}</code>-Constraints.\n</li><li>Generierung von C99-Initialisierungslisten (<code>{ .field = val, ... }</code> bzw. <code>{ val1, val2 }</code>), <code>const</code>-Strukturen für ROM/Flash oder NvM-Default-RAM-Blöcken.\n</li><li>Auflösung von <code>ReferenceValueSpecification</code> in C-Symboladressen (<code>&amp;variable</code>).\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Optionale Werte und Attribute:</strong> Sämtliche elementaren Wert-Attribute (<code>value</code>, <code>category</code>, <code>rule</code>) sowie Assoziationen (<code>+constant</code>, <code>+referenceValue</code>) und die Wurzel-Komposition (<code>+valueSpec</code>) besitzen die Multiplizität <code>[0..1]</code>.\n</li><li><strong>Leere Strukturen:</strong> Sowohl <code>ArrayValueSpecification</code> (<code>+element 0..*</code>) als auch <code>RecordValueSpecification</code> (<code>+field 0..*</code>) und <code>CompositeRuleBasedValueSpecification</code> (<code>+argument 0..*</code>) erlauben leere Kind-Kollektionen.\n</li><li><strong>Variantenauflösung:</strong> Die weitgehende Optionalisierung der Attribute und Assoziationen unterstützt Konstellationen, in denen Werte oder Referenzen erst durch Vorkompilierungs-Varianten oder nachgelagerte Prozessschritte belegt werden.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-f4b393770ca441eb", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> UML-Klassendiagramm (Ausschnitt des M2-Metamodells der AUTOSAR Classic Platform, <em>Software Component Template</em>).\n</li><li><strong>Technischer Zweck:</strong> Definition des Typ- und Aggregationsmusters für <code>ValueSpecification</code>. Es stellt das zentrale Konzept zur formalen, plattform- und sprachunabhängigen Modellierung von statischen Datenwerten, Initialisierungswerten (<code>initValue</code>), Kalibrierwerten (Calibration Parameters) und Konstanten (<code>ConstantSpecification</code>) im ARXML dar.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Zentrale Abstraktion</h5>\n<ul class=\"fig-list\"><li><strong><code>ValueSpecification</code> (abstrakt):</strong> Basisklasse aller Werteausprägungen im Metamodell.\n<ul class=\"fig-list\"><li>Attribut: <code>shortLabel: Identifier [0..1]</code>.\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">Container / Wurzel-Element</h5>\n<ul class=\"fig-list\"><li><strong><code>ConstantSpecification</code>:</strong> Spezialisierung von <code>ARElement</code>.\n<ul class=\"fig-list\"><li>Komposition: Hält über die Rolle <code>+valueSpec</code> optional eine Instanz (<code>0..1</code>) von <code>ValueSpecification</code>.\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">Spezialisierungen von <code>ValueSpecification</code></h5>\n<ul class=\"fig-list\"><li><strong><code>ConstantReference</code>:</strong> Indirektion zu einer <code>ConstantSpecification</code> über <code>+constant 0..1</code>.\n</li><li><strong><code>NumericalValueSpecification</code>:</strong> Numerischer Skalarwert; Attribut <code>value: Numerical [0..1]</code> mit <code>«atpVariation»</code>.\n</li><li><strong><code>ReferenceValueSpecification</code>:</strong> Referenzierung auf <code>DataPrototype</code> (<code>AtpPrototype</code>) über <code>+referenceValue 0..1</code>.\n</li><li><strong><code>TextValueSpecification</code>:</strong> Zeichenkettenliteral mit Attribut <code>value: VerbatimString [0..1]</code>.\n</li><li><strong><code>ApplicationValueSpecification</code>:</strong> Spezifikation auf Applikationsebene; realisiert zusätzlich <code>CompositeRuleBasedValueArgument</code>.\n<ul class=\"fig-list\"><li>Attribut: <code>category: Identifier [0..1]</code>.\n</li></ul>\n</li><li><strong><code>CompositeValueSpecification</code> (abstrakt):</strong> Basisklasse für zusammengesetzte Werte; erbt von <code>ValueSpecification</code>.\n<ul class=\"fig-list\"><li><strong><code>ArrayValueSpecification</code>:</strong> Repräsentiert Vektoren/Listen.\n<ul class=\"fig-list\"><li>Attribut: <code>intendedPartialInitializationCount: PositiveInteger [0..1]</code>.\n</li><li>Komposition: Aggregiert über <code>+element 0..* {ordered}</code> Kind-<code>ValueSpecification</code> (Stereotyp <code>«atpVariation,atpSplitable»</code>, Tag <code>vh.latestBindingTime = preCompileTime</code>).\n</li></ul>\n</li><li><strong><code>RecordValueSpecification</code>:</strong> Aggregiert über <code>+field 0..* {ordered}</code> Strukturfeld-<code>ValueSpecification</code> (Stereotyp <code>«atpVariation,atpSplitable»</code>, Tag <code>vh.latestBindingTime = preCompileTime</code>).\n</li></ul>\n</li><li><strong><code>AbstractRuleBasedValueSpecification</code> (abstrakt):</strong> Basisklasse für regelbasierte Wertdefinitionen.\n<ul class=\"fig-list\"><li><strong><code>NumericalRuleBasedValueSpecification</code>:</strong> Numerische regelbasierte Ausprägung.\n</li><li><strong><code>ApplicationRuleBasedValueSpecification</code>:</strong> Applikative regelbasierte Ausprägung; realisiert zusätzlich <code>CompositeRuleBasedValueArgument</code>.\n<ul class=\"fig-list\"><li>Attribut: <code>category: Identifier [0..1]</code>.\n</li></ul>\n</li><li><strong><code>CompositeRuleBasedValueSpecification</code>:</strong> Regelbasierte Definition zusammengesetzter Strukturen.\n<ul class=\"fig-list\"><li>Attribute: <code>maxSizeToFill: PositiveInteger [0..1]</code>, <code>rule: Identifier [0..1]</code>.\n</li><li>Komposition: Aggregiert über <code>+argument 0..* {ordered}</code> Instanzen von <code>CompositeValueSpecification</code>.\n</li></ul>\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Da es sich um ein statisches Metamodell handelt, existiert kein Laufzeit-Zustandswechsel. Der Verarbeitungsablauf erfolgt tooling- und generierungszeitlich:</p>\n<ol class=\"fig-list\"><li><strong>ARXML-Authoring &amp; Aggregation:</strong> SWC-Entwickler oder Kalibriertools definieren Initialwerte für <code>VariableDataPrototype</code> oder <code>ParameterDataPrototype</code> via geschachtelter <code>ValueSpecification</code>-Bäume.\n</li><li><strong>Pre-Compile Variant Handling:</strong> Bindung der mit <code>«atpVariation»</code> annotierten Pfade (<code>value</code>, <code>element</code>, <code>field</code>) auf Basis der System-Constant-Werte. Auflösung struktureller und numerischer Varianzen bis spätestens zur Vorkompilierphase.\n</li><li><strong>RTE-/BSW-Codegenerierung:</strong>\n<ul class=\"fig-list\"><li>Rekursive Traversierung der <code>ArrayValueSpecification</code>- und <code>RecordValueSpecification</code>-Hierarchien unter Berücksichtigung des <code>{ordered}</code>-Constraints.\n</li><li>Generierung von C99-Initialisierungslisten (<code>{ .field = val, ... }</code> bzw. <code>{ val1, val2 }</code>), <code>const</code>-Strukturen für ROM/Flash oder NvM-Default-RAM-Blöcken.\n</li><li>Auflösung von <code>ReferenceValueSpecification</code> in C-Symboladressen (<code>&amp;variable</code>).\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Normative Einstufung:</strong> Standardisiertes Metamodell der AUTOSAR Classic Platform (<em>Software Component Template</em>). Definiert verbindlich die Ausprägung und Vererbung aller Wertdefinitionen in ARXML-Modellen.\n</li><li><strong>Variabilität und Aufteilbarkeit:</strong>\n<ul class=\"fig-list\"><li>Die Aggregationen <code>element</code> und <code>field</code> sind als <code>«atpVariation,atpSplitable»</code> annotiert (Bindungszeit <code>vh.latestBindingTime = preCompileTime</code>). Sie unterstützen sowohl Variabilitätsauflösung zur Vorkompilierzeit als auch das physische Splitten über mehrere ARXML-Dateien hinweg.\n</li><li>Das Attribut <code>NumericalValueSpecification.value</code> unterliegt der Variabilität (<code>«atpVariation»</code>).\n</li></ul>\n</li><li><strong>Modellierungsregeln:</strong>\n<ul class=\"fig-list\"><li>Zusammengesetzte Werte (<code>CompositeValueSpecification</code>) müssen für strukturierte Initialisierungen entweder über explizite Felder/Elemente (<code>ArrayValueSpecification</code>, <code>RecordValueSpecification</code>) oder regelbasiert (<code>CompositeRuleBasedValueSpecification</code>) instanziiert werden.\n</li><li><code>intendedPartialInitializationCount</code> erlaubt die gezielte partielle Initialisierung von Arrays.\n</li><li>Sowohl <code>ApplicationValueSpecification</code> als auch <code>ApplicationRuleBasedValueSpecification</code> können die Rolle eines <code>CompositeRuleBasedValueArgument</code> einnehmen.\n</li><li>Konstanten (<code>ConstantSpecification</code>) können via <code>ConstantReference</code> wiederverwendet werden, um Redundanzen in SWC-Beschreibungen zu vermeiden.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-054e287cb9ebacd3", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> UML-Klassendiagramm (Ausschnitt des M2-Metamodells der AUTOSAR Classic Platform, <em>Software Component Template</em>).\n</li><li><strong>Technischer Zweck:</strong> Definition des Typ- und Aggregationsmusters für <code>ValueSpecification</code>. Es stellt das zentrale Konzept zur formalen, plattform- und sprachunabhängigen Modellierung von statischen Datenwerten, Initialisierungswerten (<code>initValue</code>), Kalibrierwerten (Calibration Parameters) und Konstanten (<code>ConstantSpecification</code>) im ARXML dar.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Zentrale Abstraktion</h5>\n<ul class=\"fig-list\"><li><strong><code>ValueSpecification</code> (abstrakt):</strong> Basisklasse aller Werteausprägungen im Metamodell.\n<ul class=\"fig-list\"><li>Attribut: <code>shortLabel: Identifier [0..1]</code>.\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">Container / Wurzel-Element</h5>\n<ul class=\"fig-list\"><li><strong><code>ConstantSpecification</code>:</strong> Spezialisierung von <code>ARElement</code>.\n<ul class=\"fig-list\"><li>Komposition: Hält über die Rolle <code>+valueSpec</code> optional eine Instanz (<code>0..1</code>) von <code>ValueSpecification</code> (Stereotyp <code>«atpSplitable»</code>).\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">Spezialisierungen von <code>ValueSpecification</code></h5>\n<ul class=\"fig-list\"><li><strong><code>ConstantReference</code>:</strong> Indirektion zu einer <code>ConstantSpecification</code> über <code>+constant 0..1</code>.\n</li><li><strong><code>NumericalValueSpecification</code>:</strong> Numerischer Skalarwert; Attribut <code>value: Numerical [0..1]</code> mit <code>«atpVariation»</code>.\n</li><li><strong><code>ReferenceValueSpecification</code>:</strong> Referenzierung auf <code>DataPrototype</code> (<code>AtpPrototype</code>) über <code>+referenceValue 0..1</code>.\n</li><li><strong><code>TextValueSpecification</code>:</strong> Zeichenkettenliteral mit Attribut <code>value: VerbatimString [0..1]</code>.\n</li><li><strong><code>ApplicationValueSpecification</code>:</strong> Spezifikation auf Applikationsebene; realisiert zusätzlich <code>CompositeRuleBasedValueArgument</code>.\n<ul class=\"fig-list\"><li>Attribut: <code>category: Identifier [0..1]</code>.\n</li></ul>\n</li><li><strong><code>CompositeValueSpecification</code> (abstrakt):</strong> Basisklasse für zusammengesetzte Werte; erbt von <code>ValueSpecification</code>.\n<ul class=\"fig-list\"><li><strong><code>ArrayValueSpecification</code>:</strong> Repräsentiert Vektoren/Listen.\n<ul class=\"fig-list\"><li>Attribut: <code>intendedPartialInitializationCount: PositiveInteger [0..1]</code>.\n</li><li>Komposition: Aggregiert über <code>+element 0..* {ordered}</code> Kind-<code>ValueSpecification</code> (Stereotyp <code>«atpVariation,atpSplitable»</code>, Tag <code>vh.latestBindingTime = preCompileTime</code>).\n</li></ul>\n</li><li><strong><code>RecordValueSpecification</code>:</strong> Aggregiert über <code>+field 0..* {ordered}</code> Strukturfeld-<code>ValueSpecification</code> (Stereotyp <code>«atpVariation,atpSplitable»</code>, Tag <code>vh.latestBindingTime = preCompileTime</code>).\n</li></ul>\n</li><li><strong><code>AbstractRuleBasedValueSpecification</code> (abstrakt):</strong> Basisklasse für regelbasierte Wertdefinitionen.\n<ul class=\"fig-list\"><li><strong><code>NumericalRuleBasedValueSpecification</code>:</strong> Numerische regelbasierte Ausprägung.\n</li><li><strong><code>ApplicationRuleBasedValueSpecification</code>:</strong> Applikative regelbasierte Ausprägung; realisiert zusätzlich <code>CompositeRuleBasedValueArgument</code>.\n<ul class=\"fig-list\"><li>Attribut: <code>category: Identifier [0..1]</code>.\n</li></ul>\n</li><li><strong><code>CompositeRuleBasedValueSpecification</code>:</strong> Regelbasierte Definition zusammengesetzter Strukturen.\n<ul class=\"fig-list\"><li>Attribute: <code>maxSizeToFill: PositiveInteger [0..1]</code>, <code>rule: Identifier [0..1]</code>.\n</li><li>Komposition: Aggregiert über <code>+argument 0..* {ordered}</code> Instanzen von <code>CompositeValueSpecification</code>.\n</li></ul>\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Da es sich um ein statisches Metamodell handelt, existiert kein Laufzeit-Zustandswechsel. Der Verarbeitungsablauf erfolgt tooling- und generierungszeitlich:</p>\n<ol class=\"fig-list\"><li><strong>ARXML-Authoring &amp; Aggregation:</strong> SWC-Entwickler oder Kalibriertools definieren Initialwerte für <code>VariableDataPrototype</code> oder <code>ParameterDataPrototype</code> via geschachtelter <code>ValueSpecification</code>-Bäume.\n</li><li><strong>Pre-Compile Variant Handling:</strong> Bindung der mit <code>«atpVariation»</code> annotierten Pfade (<code>value</code>, <code>element</code>, <code>field</code>) auf Basis der System-Constant-Werte. Auflösung struktureller und numerischer Varianzen bis spätestens zur Vorkompilierphase.\n</li><li><strong>RTE-/BSW-Codegenerierung:</strong>\n<ul class=\"fig-list\"><li>Rekursive Traversierung der <code>ArrayValueSpecification</code>- und <code>RecordValueSpecification</code>-Hierarchien unter Berücksichtigung des <code>{ordered}</code>-Constraints.\n</li><li>Generierung von C99-Initialisierungslisten (<code>{ .field = val, ... }</code> bzw. <code>{ val1, val2 }</code>), <code>const</code>-Strukturen für ROM/Flash oder NvM-Default-RAM-Blöcken.\n</li><li>Auflösung von <code>ReferenceValueSpecification</code> in C-Symboladressen (<code>&amp;variable</code>).\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Normative Einstufung:</strong> Standardisiertes Metamodell der AUTOSAR Classic Platform (<em>Software Component Template</em>). Definiert verbindlich die Ausprägung und Vererbung aller Wertdefinitionen in ARXML-Modellen.\n</li><li><strong>Variabilität und Aufteilbarkeit:</strong>\n<ul class=\"fig-list\"><li>Die Kompositionsrolle <code>ConstantSpecification.valueSpec</code> ist als <code>«atpSplitable»</code> gekennzeichnet, womit die Wertespezifikation unabhängig von der Konstantendefinition in separate ARXML-Dateifragmente ausgelagert werden kann.\n</li><li>Die Aggregationen <code>element</code> und <code>field</code> sind als <code>«atpVariation,atpSplitable»</code> annotiert (Bindungszeit <code>vh.latestBindingTime = preCompileTime</code>).\n</li><li>Das Attribut <code>NumericalValueSpecification.value</code> unterliegt der Variabilität (<code>«atpVariation»</code>).\n</li></ul>\n</li><li><strong>Modellierungsregeln:</strong>\n<ul class=\"fig-list\"><li>Zusammengesetzte Werte (<code>CompositeValueSpecification</code>) müssen für strukturierte Initialisierungen entweder über explizite Felder/Elemente (<code>ArrayValueSpecification</code>, <code>RecordValueSpecification</code>) oder regelbasiert (<code>CompositeRuleBasedValueSpecification</code>) instanziiert werden.\n</li><li><code>intendedPartialInitializationCount</code> erlaubt die gezielte partielle Initialisierung von Arrays.\n</li><li>Sowohl <code>ApplicationValueSpecification</code> als auch <code>ApplicationRuleBasedValueSpecification</code> können als <code>CompositeRuleBasedValueArgument</code> verwendet werden.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-0d0a3f3dde5d5bed", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> UML-Klassendiagramm (Ausschnitt des M2-Metamodells der AUTOSAR Classic Platform, <em>Software Component Template</em>).\n</li><li><strong>Technischer Zweck:</strong> Definition des Typ- und Aggregationsmusters für <code>ValueSpecification</code>. Es stellt das zentrale Konzept zur formalen, plattform- und sprachunabhängigen Modellierung von statischen Datenwerten, Initialisierungswerten (<code>initValue</code>), Kalibrierwerten (Calibration Parameters) und Konstanten (<code>ConstantSpecification</code>) im ARXML dar.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Zentrale Abstraktion</h5>\n<ul class=\"fig-list\"><li><strong><code>ValueSpecification</code> (abstrakt):</strong> Basisklasse aller Werteausprägungen im Metamodell.\n<ul class=\"fig-list\"><li>Attribut: <code>shortLabel: Identifier [0..1]</code>.\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">Container / Wurzel-Element</h5>\n<ul class=\"fig-list\"><li><strong><code>ConstantSpecification</code>:</strong> Spezialisierung von <code>ARElement</code>.\n<ul class=\"fig-list\"><li>Komposition: Hält über die Rolle <code>+valueSpec</code> optional eine Instanz (<code>0..1</code>) von <code>ValueSpecification</code> (Stereotyp <code>«atpSplitable»</code>).\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">Spezialisierungen von <code>ValueSpecification</code></h5>\n<ul class=\"fig-list\"><li><strong><code>ConstantReference</code>:</strong> Indirektion zu einer <code>ConstantSpecification</code> über <code>+constant 0..1</code>.\n</li><li><strong><code>NumericalValueSpecification</code>:</strong> Numerischer Skalarwert; Attribut <code>value: Numerical [0..1]</code> mit <code>«atpVariation»</code>.\n</li><li><strong><code>ReferenceValueSpecification</code>:</strong> Referenzierung auf <code>DataPrototype</code> (<code>AtpPrototype</code>) über <code>+referenceValue 0..1</code>.\n</li><li><strong><code>TextValueSpecification</code>:</strong> Zeichenkettenliteral mit Attribut <code>value: VerbatimString [0..1]</code>.\n</li><li><strong><code>ApplicationValueSpecification</code>:</strong> Spezifikation auf Applikationsebene; realisiert zusätzlich <code>CompositeRuleBasedValueArgument</code>.\n<ul class=\"fig-list\"><li>Attribut: <code>category: Identifier [0..1]</code>.\n</li></ul>\n</li><li><strong><code>CompositeValueSpecification</code> (abstrakt):</strong> Basisklasse für zusammengesetzte Werte; erbt von <code>ValueSpecification</code>.\n<ul class=\"fig-list\"><li><strong><code>ArrayValueSpecification</code>:</strong> Repräsentiert Vektoren/Listen.\n<ul class=\"fig-list\"><li>Attribut: <code>intendedPartialInitializationCount: PositiveInteger [0..1]</code>.\n</li><li>Komposition: Aggregiert über <code>+element 0..* {ordered}</code> Kind-<code>ValueSpecification</code> (Stereotyp <code>«atpVariation,atpSplitable»</code>, Tag <code>vh.latestBindingTime = preCompileTime</code>).\n</li></ul>\n</li><li><strong><code>RecordValueSpecification</code>:</strong> Aggregiert über <code>+field 0..* {ordered}</code> Strukturfeld-<code>ValueSpecification</code> (Stereotyp <code>«atpVariation,atpSplitable»</code>, Tag <code>vh.latestBindingTime = preCompileTime</code>).\n</li></ul>\n</li><li><strong><code>AbstractRuleBasedValueSpecification</code> (abstrakt):</strong> Basisklasse für regelbasierte Wertdefinitionen.\n<ul class=\"fig-list\"><li><strong><code>NumericalRuleBasedValueSpecification</code>:</strong> Numerische regelbasierte Ausprägung.\n</li><li><strong><code>ApplicationRuleBasedValueSpecification</code>:</strong> Applikative regelbasierte Ausprägung; realisiert zusätzlich <code>CompositeRuleBasedValueArgument</code>.\n<ul class=\"fig-list\"><li>Attribut: <code>category: Identifier [0..1]</code>.\n</li></ul>\n</li><li><strong><code>CompositeRuleBasedValueSpecification</code>:</strong> Regelbasierte Definition zusammengesetzter Strukturen.\n<ul class=\"fig-list\"><li>Attribute: <code>maxSizeToFill: PositiveInteger [0..1]</code>, <code>rule: Identifier [0..1]</code>.\n</li><li>Komposition: Aggregiert über <code>+argument 0..* {ordered}</code> Instanzen von <code>CompositeValueSpecification</code>.\n</li></ul>\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Da es sich um ein statisches Metamodell handelt, existiert kein Laufzeit-Zustandswechsel. Der Verarbeitungsablauf erfolgt tooling- und generierungszeitlich:</p>\n<ol class=\"fig-list\"><li><strong>ARXML-Authoring &amp; Aggregation:</strong> SWC-Entwickler oder Kalibriertools definieren Initialwerte für <code>VariableDataPrototype</code> oder <code>ParameterDataPrototype</code> via geschachtelter <code>ValueSpecification</code>-Bäume.\n</li><li><strong>Pre-Compile Variant Handling:</strong> Bindung der mit <code>«atpVariation»</code> annotierten Pfade (<code>value</code>, <code>element</code>, <code>field</code>) auf Basis der System-Constant-Werte. Auflösung struktureller und numerischer Varianzen bis spätestens zur Vorkompilierphase.\n</li><li><strong>RTE-/BSW-Codegenerierung:</strong>\n<ul class=\"fig-list\"><li>Rekursive Traversierung der <code>ArrayValueSpecification</code>- und <code>RecordValueSpecification</code>-Hierarchien unter Berücksichtigung des <code>{ordered}</code>-Constraints.\n</li><li>Generierung von C99-Initialisierungslisten (<code>{ .field = val, ... }</code> bzw. <code>{ val1, val2 }</code>), <code>const</code>-Strukturen für ROM/Flash oder NvM-Default-RAM-Blöcken.\n</li><li>Auflösung von <code>ReferenceValueSpecification</code> in C-Symboladressen (<code>&amp;variable</code>).\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Normative Einstufung:</strong> Standardisiertes Metamodell der AUTOSAR Classic Platform (<em>Software Component Template</em>). Definiert verbindlich die Ausprägung und Vererbung aller Wertdefinitionen in ARXML-Modellen.\n</li><li><strong>Variabilität und Aufteilbarkeit:</strong>\n<ul class=\"fig-list\"><li>Die Kompositionsrolle <code>ConstantSpecification.valueSpec</code> ist als <code>«atpSplitable»</code> gekennzeichnet, womit die Wertespezifikation unabhängig von der Konstantendefinition in separate ARXML-Dateifragmente ausgelagert werden kann.\n</li><li>Die Aggregationen <code>element</code> und <code>field</code> sind als <code>«atpVariation,atpSplitable»</code> annotiert (Bindungszeit <code>vh.latestBindingTime = preCompileTime</code>).\n</li><li>Das Attribut <code>NumericalValueSpecification.value</code> unterliegt der Variabilität (<code>«atpVariation»</code>).\n</li></ul>\n</li><li><strong>Modellierungsregeln:</strong>\n<ul class=\"fig-list\"><li>Zusammengesetzte Werte (<code>CompositeValueSpecification</code>) müssen für strukturierte Initialisierungen entweder über explizite Felder/Elemente (<code>ArrayValueSpecification</code>, <code>RecordValueSpecification</code>) oder regelbasiert (<code>CompositeRuleBasedValueSpecification</code>) instanziiert werden.\n</li><li><code>intendedPartialInitializationCount</code> erlaubt die gezielte partielle Initialisierung von Arrays.\n</li><li>Sowohl <code>ApplicationValueSpecification</code> als auch <code>ApplicationRuleBasedValueSpecification</code> können als <code>CompositeRuleBasedValueArgument</code> verwendet werden.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-ce1b04a35453c46b", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> UML-Klassendiagramm (Ausschnitt des M2-Metamodells der AUTOSAR Classic Platform, <em>Software Component Template</em>).\n</li><li><strong>Technischer Zweck:</strong> Definition des Typ- und Aggregationsmusters für <code>ValueSpecification</code>. Es stellt das zentrale Konzept zur formalen, plattform- und sprachunabhängigen Modellierung von statischen Datenwerten, Initialisierungswerten (<code>initValue</code>), Kalibrierwerten (Calibration Parameters) und Konstanten (<code>ConstantSpecification</code>) im ARXML dar.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Zentrale Abstraktion</h5>\n<ul class=\"fig-list\"><li><strong><code>ValueSpecification</code> (abstrakt):</strong> Basisklasse aller Werteausprägungen im Metamodell.\n<ul class=\"fig-list\"><li>Attribut: <code>shortLabel: Identifier [0..1]</code>.\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">Container / Wurzel-Element</h5>\n<ul class=\"fig-list\"><li><strong><code>ConstantSpecification</code>:</strong> Spezialisierung von <code>ARElement</code>.\n<ul class=\"fig-list\"><li>Komposition: Hält über die Rolle <code>+valueSpec</code> optional eine Instanz (<code>0..1</code>) von <code>ValueSpecification</code> (Stereotyp <code>«atpSplitable»</code>).\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">Spezialisierungen von <code>ValueSpecification</code></h5>\n<ul class=\"fig-list\"><li><strong><code>ConstantReference</code>:</strong> Indirektion zu einer <code>ConstantSpecification</code> über <code>+constant 0..1</code>.\n</li><li><strong><code>NumericalValueSpecification</code>:</strong> Numerischer Skalarwert; Attribut <code>value: Numerical [0..1]</code> mit <code>«atpVariation»</code>.\n</li><li><strong><code>ReferenceValueSpecification</code>:</strong> Referenzierung auf <code>DataPrototype</code> (<code>AtpPrototype</code>) über <code>+referenceValue 0..1</code>.\n</li><li><strong><code>TextValueSpecification</code>:</strong> Zeichenkettenliteral mit Attribut <code>value: VerbatimString [0..1]</code>.\n</li><li><strong><code>ApplicationValueSpecification</code>:</strong> Spezifikation auf Applikationsebene; realisiert zusätzlich <code>CompositeRuleBasedValueArgument</code>.\n<ul class=\"fig-list\"><li>Attribut: <code>category: Identifier [0..1]</code>.\n</li></ul>\n</li><li><strong><code>CompositeValueSpecification</code> (abstrakt):</strong> Basisklasse für zusammengesetzte Werte; erbt von <code>ValueSpecification</code>.\n<ul class=\"fig-list\"><li><strong><code>ArrayValueSpecification</code>:</strong> Repräsentiert Vektoren/Listen.\n<ul class=\"fig-list\"><li>Attribut: <code>intendedPartialInitializationCount: PositiveInteger [0..1]</code>.\n</li><li>Komposition: Aggregiert über <code>+element 0..* {ordered}</code> Kind-<code>ValueSpecification</code> (Stereotyp <code>«atpVariation,atpSplitable»</code>, Tag <code>vh.latestBindingTime = preCompileTime</code>).\n</li></ul>\n</li><li><strong><code>RecordValueSpecification</code>:</strong> Aggregiert über <code>+field 0..* {ordered}</code> Strukturfeld-<code>ValueSpecification</code> (Stereotyp <code>«atpVariation,atpSplitable»</code>, Tag <code>vh.latestBindingTime = preCompileTime</code>).\n</li></ul>\n</li><li><strong><code>AbstractRuleBasedValueSpecification</code> (abstrakt):</strong> Basisklasse für regelbasierte Wertdefinitionen.\n<ul class=\"fig-list\"><li><strong><code>NumericalRuleBasedValueSpecification</code>:</strong> Numerische regelbasierte Ausprägung.\n</li><li><strong><code>ApplicationRuleBasedValueSpecification</code>:</strong> Applikative regelbasierte Ausprägung; realisiert zusätzlich <code>CompositeRuleBasedValueArgument</code>.\n<ul class=\"fig-list\"><li>Attribut: <code>category: Identifier [0..1]</code>.\n</li></ul>\n</li><li><strong><code>CompositeRuleBasedValueSpecification</code>:</strong> Regelbasierte Definition zusammengesetzter Strukturen.\n<ul class=\"fig-list\"><li>Attribute: <code>maxSizeToFill: PositiveInteger [0..1]</code>, <code>rule: Identifier [0..1]</code>.\n</li><li>Komposition: Aggregiert über <code>+argument 0..* {ordered}</code> Instanzen von <code>CompositeValueSpecification</code>.\n</li></ul>\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Da es sich um ein statisches Metamodell handelt, existiert kein Laufzeit-Zustandswechsel. Der Verarbeitungsablauf erfolgt tooling- und generierungszeitlich:</p>\n<ol class=\"fig-list\"><li><strong>ARXML-Authoring &amp; Aggregation:</strong> SWC-Entwickler oder Kalibriertools definieren Initialwerte für <code>VariableDataPrototype</code> oder <code>ParameterDataPrototype</code> via geschachtelter <code>ValueSpecification</code>-Bäume.\n</li><li><strong>Pre-Compile Variant Handling:</strong> Bindung der mit <code>«atpVariation»</code> annotierten Pfade (<code>value</code>, <code>element</code>, <code>field</code>) auf Basis der System-Constant-Werte. Auflösung struktureller und numerischer Varianzen bis spätestens zur Vorkompilierphase.\n</li><li><strong>RTE-/BSW-Codegenerierung:</strong>\n<ul class=\"fig-list\"><li>Rekursive Traversierung der <code>ArrayValueSpecification</code>- und <code>RecordValueSpecification</code>-Hierarchien unter Berücksichtigung des <code>{ordered}</code>-Constraints.\n</li><li>Generierung von C99-Initialisierungslisten (<code>{ .field = val, ... }</code> bzw. <code>{ val1, val2 }</code>), <code>const</code>-Strukturen für ROM/Flash oder NvM-Default-RAM-Blöcken.\n</li><li>Auflösung von <code>ReferenceValueSpecification</code> in C-Symboladressen (<code>&amp;variable</code>).\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Normative Einstufung:</strong> Standardisiertes Metamodell der AUTOSAR Classic Platform (<em>Software Component Template</em>). Definiert verbindlich die Ausprägung und Vererbung aller Wertdefinitionen in ARXML-Modellen.\n</li><li><strong>Variabilität und Aufteilbarkeit:</strong>\n<ul class=\"fig-list\"><li>Die Kompositionsrolle <code>ConstantSpecification.valueSpec</code> ist als <code>«atpSplitable»</code> gekennzeichnet, womit die Wertespezifikation unabhängig von der Konstantendefinition in separate ARXML-Dateifragmente ausgelagert werden kann.\n</li><li>Die Aggregationen <code>element</code> und <code>field</code> sind als <code>«atpVariation,atpSplitable»</code> annotiert (Bindungszeit <code>vh.latestBindingTime = preCompileTime</code>).\n</li><li>Das Attribut <code>NumericalValueSpecification.value</code> unterliegt der Variabilität (<code>«atpVariation»</code>).\n</li></ul>\n</li><li><strong>Modellierungsregeln:</strong>\n<ul class=\"fig-list\"><li>Zusammengesetzte Werte (<code>CompositeValueSpecification</code>) müssen für strukturierte Initialisierungen entweder über explizite Felder/Elemente (<code>ArrayValueSpecification</code>, <code>RecordValueSpecification</code>) oder regelbasiert (<code>CompositeRuleBasedValueSpecification</code>) instanziiert werden.\n</li><li><code>intendedPartialInitializationCount</code> erlaubt die gezielte partielle Initialisierung von Arrays.\n</li><li>Sowohl <code>ApplicationValueSpecification</code> als auch <code>ApplicationRuleBasedValueSpecification</code> können als <code>CompositeRuleBasedValueArgument</code> verwendet werden.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-1843a67c3929e77c", "to": "FIG-28dd2a178e37715c", "fr": "R4.0.3", "tr": "R4.1.3", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Einführung der abstrakten Klasse <code>AbstractRuleBasedValueSpecification</code> als Subklasse von <code>ValueSpecification</code>.\n</li><li>Einführung der konkreten Subklassen <code>NumericalRuleBasedValueSpecification</code> und <code>ApplicationRuleBasedValueSpecification</code> (mit Attribut <code>category: Identifier</code>) unter <code>AbstractRuleBasedValueSpecification</code>.\n</li><li>Tag-Wert in der Variant-Annotation von <code>ArrayValueSpecification</code> und <code>RecordValueSpecification</code> typografisch angepasst auf <code>vh.latestBindingTime = preCompileTime</code>.\n</li></ul>"}, {"from": "FIG-28dd2a178e37715c", "to": "FIG-2377b1f4d59eca7b", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-2377b1f4d59eca7b", "to": "FIG-f20434401f077538", "fr": "R4.2.2", "tr": "R4.3.1", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Einführung der abstrakten Klasse <code>CompositeValueSpecification</code> als Subklasse von <code>ValueSpecification</code>; <code>ArrayValueSpecification</code> und <code>RecordValueSpecification</code> erben nun von <code>CompositeValueSpecification</code> statt direkt von <code>ValueSpecification</code>.\n</li><li>Einführung der Subklasse <code>CompositeRuleBasedValueSpecification</code> unter <code>AbstractRuleBasedValueSpecification</code> mit den Attributen <code>maxSizeToFill: PositiveInteger [0..1]</code> und <code>rule: Identifier</code>.\n</li><li><code>CompositeRuleBasedValueSpecification</code> aggregiert <code>CompositeValueSpecification</code> über eine Kompositionsbeziehung mit der Rolle <code>+argument 1..* {ordered}</code>.\n</li></ul>"}, {"from": "FIG-f20434401f077538", "to": "FIG-02f6b563e67886c9", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Bei <code>ArrayValueSpecification</code> ändert sich die Kardinalität der Kompositionsrolle <code>+element</code> von <code>1..* {ordered}</code> auf <code>0..* {ordered}</code>.\n</li></ul>"}, {"from": "FIG-02f6b563e67886c9", "to": "FIG-7944581b8e2dee93", "fr": "R18-10_R4.4.0_R1.5.0", "tr": "R19-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Bei <code>ArrayValueSpecification</code> wird das optionale Attribut <code>intendedPartialInitializationCount: PositiveInteger [0..1]</code> hinzugefügt.\n</li></ul>"}, {"from": "FIG-7944581b8e2dee93", "to": "FIG-5ec41143cb2dce14", "fr": "R19-11", "tr": "R20-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Bei <code>ConstantSpecification</code> ändert sich die Kardinalität der Komposition <code>+valueSpec</code> von <code>1</code> auf <code>0..1</code>.\n</li><li>Bei <code>ConstantReference</code> ändert sich die Multiplizität der Assoziation <code>+constant</code> von <code>1</code> auf <code>0..1</code>.\n</li><li>Bei <code>ReferenceValueSpecification</code> ändert sich die Multiplizität der Assoziation <code>+referenceValue</code> von <code>1</code> auf <code>0..1</code>.\n</li><li>Bei <code>NumericalValueSpecification</code> wird die Multiplizität des Attributs <code>value: Numerical</code> von <code>1</code> (implizit) auf <code>[0..1]</code> geändert.\n</li><li>Bei <code>TextValueSpecification</code> wird die Multiplizität des Attributs <code>value: VerbatimString</code> von <code>1</code> (implizit) auf <code>[0..1]</code> geändert.\n</li><li>Bei <code>ApplicationValueSpecification</code> wird die Multiplizität des Attributs <code>category: Identifier</code> von <code>1</code> (implizit) auf <code>[0..1]</code> geändert.\n</li><li>Bei <code>ApplicationRuleBasedValueSpecification</code> wird die Multiplizität des Attributs <code>category: Identifier</code> von <code>1</code> (implizit) auf <code>[0..1]</code> geändert.\n</li><li>Bei <code>CompositeRuleBasedValueSpecification</code> wird die Multiplizität des Attributs <code>rule: Identifier</code> von <code>1</code> (implizit) auf <code>[0..1]</code> geändert.\n</li><li>Bei <code>CompositeRuleBasedValueSpecification</code> ändert sich die Kardinalität der Aggregation <code>+argument</code> von <code>1..* {ordered}</code> auf <code>0..* {ordered}</code>.\n</li><li>Bei <code>RecordValueSpecification</code> ändert sich die Kardinalität der Komposition <code>+field</code> von <code>1..* {ordered}</code> auf <code>0..* {ordered}</code>.\n</li></ul>"}, {"from": "FIG-5ec41143cb2dce14", "to": "FIG-f4b393770ca441eb", "fr": "R20-11", "tr": "R22-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><code>ApplicationValueSpecification</code>: Zusätzliche Spezialisierung/Implementierung von <code>CompositeRuleBasedValueArgument</code>.\n</li><li><code>ApplicationRuleBasedValueSpecification</code>: Zusätzliche Spezialisierung/Implementierung von <code>CompositeRuleBasedValueArgument</code>.\n</li><li><code>ArrayValueSpecification</code>: Die Kompositionsbeziehung <code>+element</code> zu <code>ValueSpecification</code> erhält zusätzlich das Stereotyp <code>«atpSplitable»</code> (vormals nur <code>«atpVariation»</code>).\n</li><li><code>RecordValueSpecification</code>: Die Kompositionsbeziehung <code>+field</code> zu <code>ValueSpecification</code> erhält zusätzlich das Stereotyp <code>«atpSplitable»</code> (vormals nur <code>«atpVariation»</code>).\n</li></ul>"}, {"from": "FIG-f4b393770ca441eb", "to": "FIG-054e287cb9ebacd3", "fr": "R22-11", "tr": "R23-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><code>ConstantSpecification</code>: Die Kompositionsbeziehung <code>+valueSpec</code> zu <code>ValueSpecification</code> wird um das Stereotyp <code>«atpSplitable»</code> ergänzt.\n</li></ul>"}, {"from": "FIG-054e287cb9ebacd3", "to": "FIG-0d0a3f3dde5d5bed", "fr": "R23-11", "tr": "R24-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li><code>ArrayValueSpecification</code>: Die Multiplizitäts- und Rollenbeschriftung <code>0..* {ordered} +element</code> wurde vom horizontalen Linienabschnitt auf den vertikalen Linienverlauf umbrochen/verschoben.\n</li><li><code>CompositeRuleBasedValueSpecification</code>: Die Multiplizitätsbeschriftung <code>0..* {ordered}</code> der Kompositionsrolle <code>+argument</code> wurde zweizeilig formatiert.\n</li></ul>"}, {"from": "FIG-0d0a3f3dde5d5bed", "to": "FIG-ce1b04a35453c46b", "fr": "R24-11", "tr": "R25-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
